"""Tests for the Telegram cookie-jar upload (no Telegram, no network)."""

from __future__ import annotations

import unittest

from features.telegram_autonomous_hooks import cookie_jar_status

GOOD = """# Netscape HTTP Cookie File
# This file was generated by a browser extension
.youtube.com\tTRUE\t/\tTRUE\t1799999999\tSID\tabcdef
.youtube.com\tTRUE\t/\tFALSE\t1799999999\tHSID\tghijkl
"""


class CookieJarTests(unittest.TestCase):
    def test_valid_youtube_jar(self):
        ok, detail = cookie_jar_status(GOOD)
        self.assertTrue(ok)
        self.assertIn("2 youtube.com", detail)

    def test_empty_file_rejected(self):
        ok, _ = cookie_jar_status("   \n\n")
        self.assertFalse(ok)

    def test_comments_only_rejected(self):
        ok, detail = cookie_jar_status("# Netscape HTTP Cookie File\n# only comments\n")
        self.assertFalse(ok)
        self.assertIn("No cookie lines", detail)

    def test_non_youtube_jar_rejected(self):
        text = ".example.com\tTRUE\t/\tFALSE\t1\tA\tb\n"
        ok, detail = cookie_jar_status(text)
        self.assertFalse(ok)
        self.assertIn("youtube.com", detail)

    def test_wrong_format_rejected(self):
        ok, detail = cookie_jar_status("youtube.com some random text\n")
        self.assertFalse(ok)
        self.assertIn("Netscape", detail)

    def test_jar_without_primary_session_cookie_rejected(self):
        # Exactly the production failure: secure third-party cookies only, so
        # YouTube still says "Sign in to confirm you're not a bot".
        text = (
            ".youtube.com\tTRUE\t/\tTRUE\t1799999999\t__Secure-3PSID\tabc\n"
            ".youtube.com\tTRUE\t/\tTRUE\t1799999999\t__Secure-3PAPISID\tdef\n"
        )
        ok, detail = cookie_jar_status(text)
        self.assertFalse(ok)
        self.assertIn("not signed in", detail)

    def test_primary_without_companion_rejected(self):
        text = ".youtube.com\tTRUE\t/\tTRUE\t1799999999\tSID\tabc\n"
        ok, detail = cookie_jar_status(text)
        self.assertFalse(ok)
        self.assertIn("companion", detail)

    def test_secure_style_signed_in_jar_accepted(self):
        text = (
            ".youtube.com\tTRUE\t/\tTRUE\t1799999999\t__Secure-1PSID\tabc\n"
            ".youtube.com\tTRUE\t/\tTRUE\t1799999999\t__Secure-1PAPISID\tdef\n"
        )
        ok, _ = cookie_jar_status(text)
        self.assertTrue(ok)


if __name__ == "__main__":
    unittest.main()
